<script setup>
import {ref,onMounted} from 'vue';import AppShell from '../components/AppShell.vue';import {supabase} from '../services/supabase';const posts=ref([]),content=ref(''),loading=ref(true),busy=ref(false),error=ref('');async function load(){const {data}=await supabase.from('community_posts').select('*, author:profiles!community_posts_user_id_fkey(full_name)').order('created_at',{ascending:false}).limit(40);posts.value=data||[];loading.value=false}onMounted(load);async function publish(){if(!content.value.trim())return;busy.value=true;const {data:{user}}=await supabase.auth.getUser();const {error:e}=await supabase.from('community_posts').insert({user_id:user.id,content:content.value.trim()});if(e)error.value=e.message;else{content.value='';await load()}busy.value=false}
</script>
<template><AppShell title="Community" subtitle="Connect, share and grow together"><template #default><span class="eyebrow">THE CAMPUS GIG COMMUNITY</span><h1 class="page-title">A place to connect.</h1><p class="page-subtitle">Share opportunities, advice, wins and useful updates with the community.</p><form class="card composer" @submit.prevent="publish"><textarea v-model="content" class="input" placeholder="Share something useful with the community…" maxlength="1000"></textarea><div><small class="muted">Keep it respectful and helpful.</small><button class="btn btn-primary" :disabled="busy||!content.trim()">{{busy?'Posting…':'Share update'}}</button></div></form><div v-if="error" class="alert error">{{error}}</div><div v-if="loading" class="empty">Loading community updates…</div><div v-else-if="posts.length" class="feed"><article v-for="p in posts" :key="p.id" class="card"><div class="post-head"><div class="avatar">{{(p.author?.full_name||'M').slice(0,1)}}</div><div><b>{{p.author?.full_name||'Campus Gig member'}}</b><small>{{new Date(p.created_at).toLocaleString('en-ZA')}}</small></div></div><p>{{p.content}}</p></article></div><div v-else class="empty">No updates yet. Be the first to share something.</div></template></AppShell></template>
<style scoped>.composer{margin:22px 0}.composer textarea{min-height:95px}.composer>div{display:flex;justify-content:space-between;align-items:center;margin-top:10px}.feed{display:grid;gap:12px}.post-head{display:flex;align-items:center;gap:10px}.post-head b,.post-head small{display:block}.post-head small{font-size:10px;color:var(--muted);margin-top:3px}.feed article>p{font-size:14px;line-height:1.7;white-space:pre-wrap}</style>
